before.lib/accounts.ex:
defmodule Accounts do
  @doc "Public capability discovery; persistence means save/2 can store a record."
  def capabilities, do: %{persistence: true}
  def changeset(row), do: %{valid?: is_integer(row.id), changes: row}
  def save(store, row), do: Agent.update(store, &Map.put(&1, row.id, row))
  def get(store, id), do: Agent.get(store, &Map.get(&1, id))
end

